import { Hono } from 'hono'
import { createClient, type SupabaseClient } from '@supabase/supabase-js'
import { z } from 'zod'
import type { MiddlewareHandler } from 'hono'

export type Document = { id: string; owner_id: string; title: string; status: 'draft' | 'published' }
type Env = { Variables: { supabase: SupabaseClient } }
export const app = new Hono<Env>()
const input = z.strictObject({ title: z.string().trim().min(1).max(120), status: z.enum(['draft', 'published']).default('draft') })
const keyPattern = /^[a-zA-Z0-9_-]{1,64}$/
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

app.use('*', async (c, next) => { c.header('Cache-Control', 'no-store'); await next() })
app.onError((_error, c) => c.json({ error: 'internal_error' }, 500))
app.notFound(c => c.json({ error: 'not_found' }, 404))
app.get('/health', c => c.json({ status: 'ok' }))

const admit: MiddlewareHandler<Env> = async (c, next) => {
  const match = /^Bearer ([A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)$/i.exec(c.req.header('Authorization') ?? '')
  if (!match) return c.json({ error: 'unauthorized' }, 401)
  const token = match[1]
  const client = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_ANON_KEY!, {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
  })
  const { data, error } = await client.auth.getUser(token)
  if (error && (error.status ?? 0) >= 500) throw new Error('auth_unavailable')
  if (error || !data.user) return c.json({ error: 'unauthorized' }, 401)
  c.set('supabase', client)
  await next()
}

app.post('/documents', admit, async c => {
  const length = c.req.header('Content-Length')
  if (length && Number(length) > 4096) return c.json({ error: 'too_large' }, 413)
  // Bound actual bytes too, including chunked requests with no Content-Length.
  const reader = c.req.raw.body?.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  if (reader) {
    try {
      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        size += value.byteLength
        if (size > 4096) { await reader.cancel(); return c.json({ error: 'too_large' }, 413) }
        chunks.push(value)
      }
    } finally { reader.releaseLock() }
  }
  if (c.req.header('Content-Type')?.split(';', 1)[0].trim().toLowerCase() !== 'application/json') {
    return c.json({ error: 'unsupported_media_type' }, 415)
  }
  const key = c.req.header('Idempotency-Key') ?? ''
  if (!keyPattern.test(key)) return c.json({ error: 'invalid_request' }, 400)
  let parsed: ReturnType<typeof input.safeParse>
  try { parsed = input.safeParse(JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks)))) }
  catch { return c.json({ error: 'invalid_request' }, 400) }
  if (!parsed.success) return c.json({ error: 'invalid_request' }, 400)
  const { data, error } = await c.get('supabase').rpc('fp_create_document', {
    p_key: key, p_body: parsed.data, p_fail: c.req.header('X-Fixture-Fail') === 'after_document',
  })
  if (error) throw new Error('document_write_failed')
  if (data.error === 'idempotency_conflict') return c.json({ error: 'idempotency_conflict' }, 409)
  return c.json(data as { document: Document; replayed: boolean }, data.replayed ? 200 : 201)
})

app.get('/documents/:id', admit, async c => {
  const id = c.req.param('id')
  if (!uuidPattern.test(id)) return c.json({ error: 'invalid_request' }, 400)
  const { data, error } = await c.get('supabase').from('fp_documents')
    .select('id,owner_id,title,status').eq('id', id).maybeSingle()
  if (error) throw new Error('document_read_failed')
  if (!data) return c.json({ error: 'not_found' }, 404)
  return c.json({ document: data as Document })
})
