BEGIN;
CREATE TABLE public.fp_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id uuid NOT NULL,
  title text NOT NULL CHECK (length(title) BETWEEN 1 AND 120 AND title = btrim(title)),
  status text NOT NULL CHECK (status IN ('draft', 'published'))
);
CREATE INDEX fp_documents_owner ON public.fp_documents(owner_id);
CREATE TABLE public.fp_document_requests (
  owner_id uuid NOT NULL,
  key text NOT NULL CHECK (key ~ '^[a-zA-Z0-9_-]{1,64}$'),
  body jsonb NOT NULL,
  document_id uuid REFERENCES public.fp_documents(id),
  result jsonb,
  PRIMARY KEY (owner_id, key)
);
CREATE TABLE public.fp_document_audit (
  document_id uuid PRIMARY KEY REFERENCES public.fp_documents(id),
  owner_id uuid NOT NULL,
  request_key text NOT NULL,
  event text NOT NULL CHECK (event = 'created'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (owner_id, request_key) REFERENCES public.fp_document_requests(owner_id, key)
);
ALTER TABLE public.fp_documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fp_document_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fp_document_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.fp_documents, public.fp_document_requests, public.fp_document_audit FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.fp_documents TO authenticated;
CREATE POLICY fp_documents_read ON public.fp_documents FOR SELECT TO authenticated USING (owner_id = (SELECT auth.uid()));

CREATE FUNCTION public.fp_create_document(p_key text, p_body jsonb, p_fail boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
  reserved boolean;
  previous public.fp_document_requests%ROWTYPE;
  doc public.fp_documents%ROWTYPE;
  result jsonb;
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  IF p_key IS NULL OR p_key !~ '^[a-zA-Z0-9_-]{1,64}$'
    OR p_body IS NULL OR jsonb_typeof(p_body) <> 'object'
    OR NOT (p_body ? 'title' AND p_body ? 'status')
    OR (p_body - 'title' - 'status') <> '{}'::jsonb
    OR jsonb_typeof(p_body->'title') <> 'string'
    OR jsonb_typeof(p_body->'status') <> 'string'
    OR length(p_body->>'title') NOT BETWEEN 1 AND 120
    OR (p_body->>'title') <> btrim(p_body->>'title')
    OR (p_body->>'status') NOT IN ('draft', 'published')
  THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE = '22023'; END IF;

  -- The unique owner/key reservation serializes concurrent callers. A failed
  -- transaction releases it; a committed winner is read by the next statement.
  INSERT INTO public.fp_document_requests(owner_id, key, body)
    VALUES (actor, p_key, p_body) ON CONFLICT DO NOTHING RETURNING true INTO reserved;
  IF reserved IS DISTINCT FROM true THEN
    SELECT * INTO STRICT previous FROM public.fp_document_requests WHERE owner_id = actor AND key = p_key;
    IF previous.body <> p_body THEN RETURN jsonb_build_object('error', 'idempotency_conflict'); END IF;
    RETURN jsonb_build_object('document', previous.result, 'replayed', true);
  END IF;
  INSERT INTO public.fp_documents(owner_id, title, status)
    VALUES (actor, p_body->>'title', p_body->>'status') RETURNING * INTO doc;
  IF p_fail THEN RAISE EXCEPTION 'fixture_failure' USING ERRCODE = 'P0001'; END IF;
  INSERT INTO public.fp_document_audit(document_id, owner_id, request_key, event)
    VALUES (doc.id, actor, p_key, 'created');
  result := jsonb_build_object('id', doc.id, 'owner_id', doc.owner_id, 'title', doc.title, 'status', doc.status);
  UPDATE public.fp_document_requests SET document_id = doc.id, result = result
    WHERE owner_id = actor AND key = p_key;
  RETURN jsonb_build_object('document', result, 'replayed', false);
END;
$$;
REVOKE ALL ON FUNCTION public.fp_create_document(text, jsonb, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fp_create_document(text, jsonb, boolean) TO authenticated;
NOTIFY pgrst, 'reload schema';
COMMIT;
